      "explanation": "\n        <div class=\"eng-formula-box\">\n          <strong class=\"eng-formula-title\">1. Bản chất & Công thức chuyển đổi Câu Động từ sang Cụm Danh từ</strong>\n          • <b>Bản chất:</b> Trong văn viết học thuật B2–C1, người viết thường chuyển <b>Động từ (Verb)</b> hoặc <b>Tính từ (Adjective)</b> thành <b>Danh từ trung tâm (Head Noun)</b> để tạo giọng văn khách quan, cô đọng và giàu thông tin.<br/>\n          • <b>Quy tắc biến đổi:</b><br/>\n          <code>S + Verb + Adverb</code> ➔ <code>The + Adjective + Noun (of + S) + Verb học thuật</code><br/>\n          <i>Ví dụ:</i> The university <b>analyzed</b> the data <b>carefully</b>. ➔ A <b>careful analysis</b> of the data was conducted by the university.\n        </div>\n        <div class=\"eng-formula-box\">\n          <strong class=\"eng-formula-title\">2. Các cặp Động từ / Tính từ → Danh từ học thuật trọng tâm</strong>\n          • <code>implement (v)</code> ➔ <code>implementation (n)</code> (sự triển khai)<br/>\n          • <code>proliferate (v)</code> ➔ <code>proliferation (n)</code> (sự bùng nổ, lan rộng)<br/>\n          • <code>expand (v)</code> ➔ <code>expansion (n)</code> (sự mở rộng)<br/>\n          • <code>complex (adj)</code> ➔ <code>complexity (n)</code> (độ phức tạp)<br/>\n          • <code>disparate (adj)</code> ➔ <code>disparity (n)</code> (sự chênh lệch)\n        </div>\n      ",
