      "memoryTip": "4 cấp độ Hedging chuẩn học thuật: Động từ (tend to / appear to) — Động từ báo cáo (suggest / indicate) — Tính từ khách quan (It is plausible that) — Trạng từ (arguably / purportedly)!"
