      "commonMistake": {
        "wrong": "The outbreak was stemmed from poor water filtration.",
        "right": "The outbreak **stemmed from** poor water filtration.",
        "note": "Giống như 'originate from' hay 'result from', cụm 'stem from' (bắt nguồn từ) KHÔNG BAO GIỜ chia ở thể bị động!"
      },
      "memoryTip": "Phân biệt cặp đôi nhân quả: 'A stems from B' (chủ động 100%) = 'A is attributed to B' (bị động); còn 'account for' vừa là 'chiếm %' vừa là 'giải thích cho'!"
