    "grammar": {
      "point": "KẾT HỢP TỪ HỌC THUẬT: ĐỘNG TỪ + DANH TỪ (VERB + NOUN COLLOCATIONS)",
      "explanation": "\n        <div class=\"eng-formula-box\">\n          <strong class=\"eng-formula-title\">1. Tại sao không dùng 'make' hay 'do' cho mọi danh từ ở trình độ B2?</strong>\n          • Ở trình độ B2–C1 (IELTS Writing 7.0+), việc dùng đúng <b>Verb + Noun Collocation</b> quyết định điểm <i>Lexical Resource</i>:<br/>\n          • <code>conduct / carry out / undertake + research / a survey / an investigation</code> (KHÔNG viết <i>make research</i>).<br/>\n          • <code>reach / arrive at + a consensus / a compromise</code> (đạt được sự đồng thuận — KHÔNG viết <i>do a consensus</i>).<br/>\n          • <code>pose + a threat / a challenge / a risk + to...</code> (tạo ra mối đe dọa/thách thức cho...).\n        </div>\n        <div class=\"eng-formula-box\">\n          <strong class=\"eng-formula-title\">2. Nhóm Collocations Quản lý & Tác động học thuật</strong>\n          • <code>exert + influence / pressure / control + on/over + N</code> (tác động ảnh hưởng / gây áp lực lên...).<br/>\n          • <code>allocate + resources / funds / capital + to + N</code> (phân bổ nguồn lực/vốn cho...).<br/>\n          • <code>bridge + the gap / the divide + between A and B</code> (thu hẹp khoảng cách giữa A và B).<br/>\n          • <code>yield + results / insights / returns</code> (mang lại kết quả / góc nhìn sâu sắc / lợi nhuận).\n        </div>\n      ",
      "examples": [
        {
          "en": "Before launching the product, the firm <b>conducted extensive research</b> into regional demographics.",
          "vi": "Trước khi ra mắt sản phẩm, công ty đã tiến hành nghiên cứu sâu rộng về nhân khẩu học khu vực."
        },
        {
          "en": "Peer recommendations <b>exert far greater influence on</b> purchasing decisions than banner ads.",
          "vi": "Lời giới thiệu từ bạn bè có sức ảnh hưởng lớn hơn nhiều đến quyết định mua hàng so với quảng cáo biểu ngữ."
        },
        {
          "en": "Rising inflation <b>poses a direct threat to</b> discretionary consumer spending.",
          "vi": "Lạm phát gia tăng tạo ra một mối đe dọa trực tiếp đối với chi tiêu tiêu dùng không thiết yếu."
        },
        {
          "en": "The committee failed to <b>reach a consensus</b> on how to <b>allocate resources</b> for the next fiscal year.",
          "vi": "Ủy ban đã không đạt được sự đồng thuận về cách phân bổ nguồn lực cho năm tài chính tiếp theo."
        }
      ],
      "commonMistake": {
        "wrong": "The marketing team made a research on consumer behavior.",
        "right": "The marketing team **conducted research** on consumer behavior.",
        "note": "2 lỗi kinh điển trong 1 câu: (1) Đi với 'research' phải dùng 'conduct / carry out / do' (không dùng 'make'), và (2) 'research' là danh từ KHÔNG đếm được nên tuyệt đối không có 'a' hay 'researches'!"
      },
      "memoryTip": "Khắc cốt ghi tâm 6 cặp bài trùng B2: CONDUCT research — REACH a consensus — POSE a threat — BRIDGE the gap — EXERT influence — ALLOCATE resources!"
    },
    "dialogue": {
      "titleVi": "Tình huống: Giám đốc chiến lược trình bày báo cáo hành vi người tiêu dùng với ban giám đốc",
      "lines": [
        {
          "speaker": "Ms. Dang",
          "en": "Over the past quarter, our analytics team conducted research on shifting consumer demographics.",
          "vi": "Trong quý vừa qua, đội ngũ phân tích của chúng ta đã tiến hành nghiên cứu về sự dịch chuyển nhân khẩu học người tiêu dùng."
        },
        {
          "speaker": "Mr. Vance",
          "en": "Did the longitudinal survey yield results that explain our declining retention rate?",
          "vi": "Cuộc khảo sát dọc có mang lại kết quả nào giải thích cho tỷ lệ giữ chân khách hàng đang sụt giảm của chúng ta không?"
        },
        {
          "speaker": "Ms. Dang",
          "en": "Yes. Market saturation and aggressive discounting by rivals pose a serious threat to our core brand.",
          "vi": "Có. Sự bão hòa thị trường và việc giảm giá ồ ạt của các đối thủ đang tạo ra mối đe dọa nghiêm trọng cho thương hiệu cốt lõi của chúng ta."
        },
        {
          "speaker": "Mr. Vance",
          "en": "How can we bridge the gap between our heritage image and younger, sustainability-conscious buyers?",
          "vi": "Làm thế nào chúng ta có thể thu hẹp khoảng cách giữa hình ảnh truyền thống của mình với nhóm người mua trẻ có ý thức về sự bền vững?"
        },
        {
          "speaker": "Ms. Dang",
          "en": "Eco-certifications exert strong influence on their choices, so we must address the issue of plastic packaging.",
          "vi": "Các chứng nhận sinh thái có ảnh hưởng mạnh mẽ đến lựa chọn của họ, vì vậy chúng ta phải giải quyết vấn đề bao bì nhựa."
        },
        {
          "speaker": "Mr. Vance",
          "en": "I agree. Let's reach a consensus today on how to allocate resources toward biodegradable materials.",
          "vi": "Tôi đồng ý. Hãy đạt được sự đồng thuận ngay hôm nay về cách phân bổ nguồn lực cho các vật liệu phân hủy sinh học."
        }
      ]
    },
