      "explanation": "\n        <div class=\"eng-formula-box\">\n          <strong class=\"eng-formula-title\">1. Nhóm Tiền tố Học thuật thay đổi Nghĩa của Động từ (Academic Prefixes)</strong>\n          • <code>out-</code> (vượt hơn / nhiều hơn): <code>outperform</code> (hiệu suất vượt trội), <code>outweigh</code> (nặng ký/quan trọng hơn), <code>outnumber</code> (đông hơn).<br/>\n          • <code>over-</code> (quá mức) ↔ <code>under-</code> (dưới mức / thiếu): <code>overstate / understate</code>, <code>overestimate / underestimate</code>, <code>underfunded</code> (thiếu kinh phí).<br/>\n          • <code>mis-</code> (sai lệch): <code>misinterpret</code> (hiểu sai), <code>misdiagnose</code> (chẩn đoán sai), <code>misallocate</code> (phân bổ sai).<br/>\n          • <code>counter-</code> (ngược lại / chống lại): <code>counteract</code> (trung hòa/chống lại), <code>counterproductive</code> (phản tác dụng).\n        </div>\n        <div class=\"eng-formula-box\">\n          <strong class=\"eng-formula-title\">2. Nhóm Hậu tố Chuyển đổi Từ loại (Derivational Suffixes)</strong>\n          • <b>Tạo Động từ:</b> <code>-ize / -ise</code> (<i>synthesize, neutralize,commercialize</i>), <code>-ify</code> (<i>modify, classify,codify</i>).<br/>\n          • <b>Tạo Danh từ:</b> <code>-ity</code> (<i>viable ➔ viability; mutable ➔ mutability</i>), <code>-ment</code> (<i>assess ➔ assessment</i>), <code>-tion</code> (<i>mutate ➔ mutation</i>).<br/>\n          • <b>Tạo Tính từ:</b> <code>-able / -ible</code> (<i>viable, reversible, heritable</i>), <code>-ive</code> (<i>preventive, defective</i>), <code>-ic</code> (<i>therapeutic, genetic</i>).\n        </div>\n      ",
