      "explanation": "\n        <div class=\"eng-formula-box\">\n          <strong class=\"eng-formula-title\">1. Quy tắc 4 Không trong Văn viết Trang trọng (Formal Academic & Official Prose)</strong>\n          1. <b>Không viết tắt (No Contractions):</b> Viết <code>cannot, do not, will not, it is</code> thay vì <i>can't, don't, won't, it's</i>.<br/>\n          2. <b>Thay Động từ đa từ suồng sã bằng Động từ Đơn âm gốc Latin (Single-Verb Lexical Elevation):</b><br/>\n          • <code>find out</code> ➔ <code>ascertain / determine</code> | <code>put right / fix</code> ➔ <code>rectify</code><br/>\n          • <code>speed up</code> ➔ <code>expedite / accelerate</code> | <code>start / kick off</code> ➔ <code>commence / initiate</code><br/>\n          • <code>end / wrap up</code> ➔ <code>terminate / conclude</code> | <code>try hard</code> ➔ <code>endeavor</code>\n        </div>\n        <div class=\"eng-formula-box\">\n          <strong class=\"eng-formula-title\">2. Nâng cấp Cụm Giới từ & Cấu trúc Lịch sự Khách quan</strong>\n          • <code>before</code> ➔ <code>prior to</code> | <code>after</code> ➔ <code>subsequent to / following</code><br/>\n          • <code>about</code> ➔ <code>regarding / concerning / with regard to</code><br/>\n          • <code>as rules say</code> ➔ <code>in accordance with / pursuant to regulations</code><br/>\n          • <code>Can you tell me...?</code> ➔ <code>I would appreciate it if you could inform me whether...</code>\n        </div>\n      ",
