      "explanation": "\n        <div class=\"eng-formula-box\">\n          <strong class=\"eng-formula-title\">1. Thành ngữ Trang trọng (Day 81) & Cấu tạo từ Khoa học (Day 82)</strong>\n          • <b>Formal Idioms:</b> <code>a double-edged sword</code> (con dao hai lưỡi), <code>the tip of the iceberg</code> (phần nổi của tảng băng), <code>by and large</code> (nhìn chung), <code>a stumbling block (to)</code> (rào cản), <code>a watershed moment</code> (bước ngoặt), <code>pave the way for</code> (mở đường cho), <code>food for thought</code> (điều đáng suy ngẫm).<br/>\n          • <b>Prefixes & Suffixes:</b> <code>out-</code> (<i>outperform, outweigh</i>), <code>counter-</code> (<i>counteract, counterproductive</i>), <code>mis-</code> (<i>misinterpret</i>), <code>over-/under-</code> (<i>overstate, underestimate</i>), <code>-ize</code> (<i>synthesize</i>), <code>-ity</code> (<i>viability</i>).\n        </div>\n        <div class=\"eng-formula-box\">\n          <strong class=\"eng-formula-title\">2. Cấu trúc Song hành (Day 83) & Chuyển đổi Register (Day 84)</strong>\n          • <b>Parallelism:</b> Đồng nhất từ loại/cấu trúc trong chuỗi <code>A, B, and C</code> và sau các cặp <code>both...and, either...or, neither...nor, not only...but also</code>.<br/>\n          • <b>Register Transfer:</b> <code>commence</code> (= start), <code>terminate</code> (= end), <code>ascertain</code> (= find out), <code>rectify</code> (= fix), <code>expedite</code> (= speed up), <code>endeavor</code> (= try), <code>prior to + N/V-ing</code> (= before), <code>in accordance with</code> (= following).\n        </div>\n      ",
