        "note": "Khi mốc quy chiếu nằm trong quá khứ (was signed in 1953), hành động kéo dài trước đó bắt buộc phải lùi về Quá khứ hoàn thành tiếp diễn (had been fighting), KHÔNG dùng Hiện tại hoàn thành tiếp diễn!"
