          "en": "Biophilic design <b>not only mitigates</b> the urban heat island effect <b>but also enhances</b> mental well-being.",
          "vi": "Thiết kế ưa sinh học không chỉ giảm thiểu hiệu ứng đảo nhiệt đô thị mà còn nâng cao sức khỏe tinh thần."
