      "explanation": "\n        <div class=\"eng-formula-box\">\n          <strong class=\"eng-formula-title\">1. Hệ thống Hóa 6 Chặng Lộ trình Ngữ pháp (Stages 1–6 Overview)</strong>\n          • <b>Stages 1–2 (A1–A2):</b> 12 Thì động từ, Mạo từ, Lượng từ, So sánh, Câu điều kiện loại 1 & 2, Động từ khuyết thiếu.<br/>\n          • <b>Stages 3–4 (A2+–B1):</b> Thể Bị động, Câu tường thuật, Tương lai tiếp diễn, Suy đoán (<i>must/can't/might</i>), <i>Used to / Be used to</i>, Danh động từ & Nguyên thể, Cụm động từ cơ bản, Cấu trúc cầu khiến (<i>have/get sth done</i>).<br/>\n          • <b>Stage 5 (B1+ Upper-Intermediate):</b> Điều kiện loại 3 & Hỗn hợp, <i>Wish / If only</i>, Bị động khách quan (<i>is said to have V3</i>), Mệnh đề phân từ, Đảo ngữ, Câu chẻ nhấn mạnh, Thể giả định (<i>Subjunctive</i>).\n        </div>\n        <div class=\"eng-formula-box\">\n          <strong class=\"eng-formula-title\">2. Đỉnh cao Học thuật Chặng 6 (B2 Academic Mastery — Days 71–90)</strong>\n          • <b>Cú pháp & Văn phong Học thuật:</b> Danh từ hóa (<i>Nominalization</i>), Ngôn ngữ Rào đón (<i>Hedging: tend to, appear to, arguably</i>), Từ nối Diễn ngôn (<i>Notwithstanding, Nevertheless, Consequently, Conversely</i>), Tỉnh lược & Thế từ (<i>do so, one/ones, that of/those of</i>), Cấu trúc Song hành (<i>Parallelism</i>), Cụm Đồng vị ngữ (<i>Appositives</i>) & Chuyển đổi Register trang trọng.\n        </div>\n      ",
